-- ────────────────────────────────────────────────────────────────────────────
-- 00000000000000_baseline_schema.sql
--
-- Generated by Phase B1 on 2026-05-04 from production catalog (information_schema
-- + pg_class + pg_constraint + pg_indexes). Represents the 26 base tables that
-- the 32 canonical migrations REFERENCE but do not CREATE — they were applied
-- out-of-band (via SQL Editor or pre-canonical scripts) and have no source-
-- of-truth migration in supabase_migrations.schema_migrations.
--
-- Filename uses 14 zeros so this file lex-sorts BEFORE every real timestamped
-- migration (Supabase applies in lex order).
--
-- Coverage:
--   ✓ CREATE TABLE IF NOT EXISTS for each base table (current prod columns,
--     types, defaults, NOT NULL flags)
--   ✓ PRIMARY KEY constraints
--   ✓ UNIQUE constraints (table-level)
--   ✓ CHECK constraints (named, idempotency-guarded via DO blocks)
--   ✓ Non-PK / non-table-level-UNIQUE indexes (CREATE INDEX IF NOT EXISTS)
--
-- Intentional EXCLUSIONS (not added by this baseline; left for follow-up):
--   ✗ Foreign keys to public.* — added in a follow-up baseline FK migration
--     so this file can apply without circular dependency on out-of-order CREATE
--   ✗ Foreign keys to auth.* — Supabase manages auth.users; replay env may
--     not have it
--   ✗ RLS policies — managed by separate RLS migration (Phase D)
--   ✗ Triggers, functions, views, sequences (other than serials)
--   ✗ Supabase-managed schemas: auth, storage, realtime, vault, extensions
--
-- Idempotency: every statement uses IF NOT EXISTS or DO-block guard so this
-- file is safe to re-apply.
--
-- Tables included (26):
--   access_requests, action_pricing_config, community_ai_actions,
--   community_ai_platform_tokens, companies, company_domains,
--   credit_transactions, daily_content_plans, domain_eligibility_cache,
--   domain_whitelist, email_jobs, free_credit_claims, free_credit_profiles,
--   invitations, llm_model_pricing, organization_credits,
--   platform_oauth_configs, scheduled_posts, social_accounts,
--   super_admin_audit_logs, unified_transactions, usage_events,
--   user_company_roles, user_override, user_preferences, users
-- ────────────────────────────────────────────────────────────────────────────

-- Required extensions (referenced by some default expressions)
CREATE EXTENSION IF NOT EXISTS pgcrypto;     -- gen_random_uuid()
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

