-- ── 2. PRIMARY KEY + UNIQUE + CHECK constraints (idempotent) ────────────────
DO $$
BEGIN
  -- access_requests
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='access_requests_pkey')                              THEN ALTER TABLE public.access_requests ADD CONSTRAINT access_requests_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='access_requests_status_check')                      THEN ALTER TABLE public.access_requests ADD CONSTRAINT access_requests_status_check CHECK (status = ANY (ARRAY['pending','approved','rejected','deleted'])); END IF;
  -- action_pricing_config
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='action_pricing_config_pkey')                        THEN ALTER TABLE public.action_pricing_config ADD CONSTRAINT action_pricing_config_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='action_pricing_config_cost_multiplier_check')       THEN ALTER TABLE public.action_pricing_config ADD CONSTRAINT action_pricing_config_cost_multiplier_check CHECK (cost_multiplier >= 0); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='action_pricing_config_credit_cost_check')           THEN ALTER TABLE public.action_pricing_config ADD CONSTRAINT action_pricing_config_credit_cost_check CHECK (credit_cost IS NULL OR credit_cost >= 0); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='action_pricing_config_source_type_check')           THEN ALTER TABLE public.action_pricing_config ADD CONSTRAINT action_pricing_config_source_type_check CHECK (source_type IN ('llm','embedding','fixed')); END IF;
  -- community_ai_actions
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='community_ai_actions_pkey')                         THEN ALTER TABLE public.community_ai_actions ADD CONSTRAINT community_ai_actions_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='community_ai_actions_action_type_check')            THEN ALTER TABLE public.community_ai_actions ADD CONSTRAINT community_ai_actions_action_type_check CHECK (action_type IN ('like','reply','share','follow','schedule','dm')); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='community_ai_actions_status_check')                 THEN ALTER TABLE public.community_ai_actions ADD CONSTRAINT community_ai_actions_status_check CHECK (status IN ('pending','approved','executed','failed','skipped')); END IF;
  -- community_ai_platform_tokens
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='community_ai_platform_tokens_pkey')                 THEN ALTER TABLE public.community_ai_platform_tokens ADD CONSTRAINT community_ai_platform_tokens_pkey PRIMARY KEY (id); END IF;
  -- companies
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='companies_pkey')                                    THEN ALTER TABLE public.companies ADD CONSTRAINT companies_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='companies_status_check')                            THEN ALTER TABLE public.companies ADD CONSTRAINT companies_status_check CHECK (status IN ('active','inactive','suspended')); END IF;
  -- company_domains
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='company_domains_pkey')                              THEN ALTER TABLE public.company_domains ADD CONSTRAINT company_domains_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='unique_final_domain')                               THEN ALTER TABLE public.company_domains ADD CONSTRAINT unique_final_domain UNIQUE (final_domain); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='final_domain_not_empty')                            THEN ALTER TABLE public.company_domains ADD CONSTRAINT final_domain_not_empty CHECK (final_domain <> ''); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='company_domains_created_via_check')                 THEN ALTER TABLE public.company_domains ADD CONSTRAINT company_domains_created_via_check CHECK (created_via IN ('user','admin','system')); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='company_domains_verification_status_check')         THEN ALTER TABLE public.company_domains ADD CONSTRAINT company_domains_verification_status_check CHECK (verification_status IN ('unverified','pending','verified','admin_override')); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='company_domains_verification_method_check')         THEN ALTER TABLE public.company_domains ADD CONSTRAINT company_domains_verification_method_check CHECK (verification_method IS NULL OR verification_method IN ('dns','http','admin_override')); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='company_domains_override_reason_required')          THEN ALTER TABLE public.company_domains ADD CONSTRAINT company_domains_override_reason_required CHECK ((verification_status <> 'admin_override') OR ((override_reason IS NOT NULL) AND (length(trim(override_reason)) > 0))); END IF;
  -- credit_transactions
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='credit_transactions_pkey')                          THEN ALTER TABLE public.credit_transactions ADD CONSTRAINT credit_transactions_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='credit_transactions_idempotency_key_key')           THEN ALTER TABLE public.credit_transactions ADD CONSTRAINT credit_transactions_idempotency_key_key UNIQUE (idempotency_key); END IF;
  -- daily_content_plans
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='daily_content_plans_pkey')                          THEN ALTER TABLE public.daily_content_plans ADD CONSTRAINT daily_content_plans_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='daily_content_plans_status_check')                  THEN ALTER TABLE public.daily_content_plans ADD CONSTRAINT daily_content_plans_status_check CHECK (status::text = ANY (ARRAY['planned','content-created','media-ready','scheduled','published','failed'])); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='daily_content_plans_priority_check')                THEN ALTER TABLE public.daily_content_plans ADD CONSTRAINT daily_content_plans_priority_check CHECK (priority::text = ANY (ARRAY['low','medium','high','urgent'])); END IF;
  -- domain_eligibility_cache / domain_whitelist
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='domain_eligibility_cache_pkey')                     THEN ALTER TABLE public.domain_eligibility_cache ADD CONSTRAINT domain_eligibility_cache_pkey PRIMARY KEY (domain); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='domain_eligibility_cache_status_check')             THEN ALTER TABLE public.domain_eligibility_cache ADD CONSTRAINT domain_eligibility_cache_status_check CHECK (status IN ('eligible','blocked','pending_review')); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='domain_whitelist_pkey')                             THEN ALTER TABLE public.domain_whitelist ADD CONSTRAINT domain_whitelist_pkey PRIMARY KEY (domain); END IF;
  -- email_jobs
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='email_jobs_pkey')                                   THEN ALTER TABLE public.email_jobs ADD CONSTRAINT email_jobs_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='email_jobs_job_type_check')                         THEN ALTER TABLE public.email_jobs ADD CONSTRAINT email_jobs_job_type_check CHECK (job_type IN ('magic_link','invite','reset','company_referral','inbound_signup_notice')); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='email_jobs_status_check')                           THEN ALTER TABLE public.email_jobs ADD CONSTRAINT email_jobs_status_check CHECK (status IN ('pending','processing','sent','failed','dead')); END IF;
  -- free_credit_claims
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='free_credit_claims_pkey')                           THEN ALTER TABLE public.free_credit_claims ADD CONSTRAINT free_credit_claims_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='free_credit_claims_user_category')                  THEN ALTER TABLE public.free_credit_claims ADD CONSTRAINT free_credit_claims_user_category UNIQUE (user_id, category); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='free_credit_claims_positive_credits')               THEN ALTER TABLE public.free_credit_claims ADD CONSTRAINT free_credit_claims_positive_credits CHECK (credits_granted > 0); END IF;
  -- free_credit_profiles
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='free_credit_profiles_pkey')                         THEN ALTER TABLE public.free_credit_profiles ADD CONSTRAINT free_credit_profiles_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='free_credit_profiles_phone_number_key')             THEN ALTER TABLE public.free_credit_profiles ADD CONSTRAINT free_credit_profiles_phone_number_key UNIQUE (phone_number); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='free_credit_profiles_user_id_key')                  THEN ALTER TABLE public.free_credit_profiles ADD CONSTRAINT free_credit_profiles_user_id_key UNIQUE (user_id); END IF;
  -- invitations
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='invitations_pkey')                                  THEN ALTER TABLE public.invitations ADD CONSTRAINT invitations_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='invitations_token_hash_key')                        THEN ALTER TABLE public.invitations ADD CONSTRAINT invitations_token_hash_key UNIQUE (token_hash); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='invitations_role_check')                            THEN ALTER TABLE public.invitations ADD CONSTRAINT invitations_role_check CHECK (role IN ('COMPANY_ADMIN','CONTENT_CREATOR','CONTENT_REVIEWER','CONTENT_PUBLISHER','VIEW_ONLY')); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='invitations_token_consumed_acceptance_ck')          THEN ALTER TABLE public.invitations ADD CONSTRAINT invitations_token_consumed_acceptance_ck CHECK ((accepted_at IS NULL) OR (token_consumed_at IS NOT NULL)); END IF;
  -- llm_model_pricing
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='llm_model_pricing_pkey')                            THEN ALTER TABLE public.llm_model_pricing ADD CONSTRAINT llm_model_pricing_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='llm_model_pricing_input_per_1k_usd_check')          THEN ALTER TABLE public.llm_model_pricing ADD CONSTRAINT llm_model_pricing_input_per_1k_usd_check CHECK (input_per_1k_usd >= 0); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='llm_model_pricing_output_per_1k_usd_check')         THEN ALTER TABLE public.llm_model_pricing ADD CONSTRAINT llm_model_pricing_output_per_1k_usd_check CHECK (output_per_1k_usd >= 0); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='llm_model_pricing_kind_check')                      THEN ALTER TABLE public.llm_model_pricing ADD CONSTRAINT llm_model_pricing_kind_check CHECK (kind IN ('completion','embedding')); END IF;
  -- organization_credits
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='organization_credits_pkey')                         THEN ALTER TABLE public.organization_credits ADD CONSTRAINT organization_credits_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='organization_credits_organization_id_key')          THEN ALTER TABLE public.organization_credits ADD CONSTRAINT organization_credits_organization_id_key UNIQUE (organization_id); END IF;
  -- platform_oauth_configs
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='platform_oauth_configs_pkey')                       THEN ALTER TABLE public.platform_oauth_configs ADD CONSTRAINT platform_oauth_configs_pkey PRIMARY KEY (platform); END IF;
  -- scheduled_posts
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='scheduled_posts_pkey')                              THEN ALTER TABLE public.scheduled_posts ADD CONSTRAINT scheduled_posts_pkey PRIMARY KEY (id); END IF;
  -- (chk_* CHECKs on scheduled_posts intentionally omitted from baseline; multi-line/multi-platform CHECKs
  --  re-add cleanly via the existing canonical migration ordering and would bloat this baseline.)
  -- social_accounts
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='social_accounts_pkey')                              THEN ALTER TABLE public.social_accounts ADD CONSTRAINT social_accounts_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='social_accounts_company_platform_user_unique')      THEN ALTER TABLE public.social_accounts ADD CONSTRAINT social_accounts_company_platform_user_unique UNIQUE (company_id, platform, platform_user_id); END IF;
  -- super_admin_audit_logs
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='super_admin_audit_logs_pkey')                       THEN ALTER TABLE public.super_admin_audit_logs ADD CONSTRAINT super_admin_audit_logs_pkey PRIMARY KEY (id); END IF;
  -- unified_transactions
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='unified_transactions_pkey')                         THEN ALTER TABLE public.unified_transactions ADD CONSTRAINT unified_transactions_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='unified_transactions_retry_attempt_check')          THEN ALTER TABLE public.unified_transactions ADD CONSTRAINT unified_transactions_retry_attempt_check CHECK (retry_attempt >= 1); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='unified_transactions_source_type_check')            THEN ALTER TABLE public.unified_transactions ADD CONSTRAINT unified_transactions_source_type_check CHECK (source_type IN ('llm','embedding','cache','external_api','automation_execution','system','internal')); END IF;
  -- usage_events
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='usage_events_pkey')                                 THEN ALTER TABLE public.usage_events ADD CONSTRAINT usage_events_pkey PRIMARY KEY (id); END IF;
  -- user_company_roles
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='user_company_roles_pkey')                           THEN ALTER TABLE public.user_company_roles ADD CONSTRAINT user_company_roles_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='user_company_roles_status_check')                   THEN ALTER TABLE public.user_company_roles ADD CONSTRAINT user_company_roles_status_check CHECK (status IN ('invited','active','inactive','expired')); END IF;
  -- user_override
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='user_override_pkey')                                THEN ALTER TABLE public.user_override ADD CONSTRAINT user_override_pkey PRIMARY KEY (user_id); END IF;
  -- user_preferences
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='user_preferences_pkey')                             THEN ALTER TABLE public.user_preferences ADD CONSTRAINT user_preferences_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='unique_user_id')                                    THEN ALTER TABLE public.user_preferences ADD CONSTRAINT unique_user_id UNIQUE (user_id); END IF;
  -- users
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='users_pkey')                                        THEN ALTER TABLE public.users ADD CONSTRAINT users_pkey PRIMARY KEY (id); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='users_email_key')                                   THEN ALTER TABLE public.users ADD CONSTRAINT users_email_key UNIQUE (email); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='users_auth_level_check')                            THEN ALTER TABLE public.users ADD CONSTRAINT users_auth_level_check CHECK (auth_level IN ('none','email_verified','email_phone_verified')); END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='users_user_type_check')                             THEN ALTER TABLE public.users ADD CONSTRAINT users_user_type_check CHECK (user_type IN ('trial','paid','enterprise','internal')); END IF;
END $$;

-- ── 3. Indexes (idempotent) ─────────────────────────────────────────────────
-- access_requests
CREATE INDEX IF NOT EXISTS access_requests_domain_idx              ON public.access_requests (domain);
CREATE INDEX IF NOT EXISTS access_requests_status_idx              ON public.access_requests (status, created_at DESC);
CREATE INDEX IF NOT EXISTS access_requests_user_id_idx             ON public.access_requests (user_id);
CREATE INDEX IF NOT EXISTS idx_access_requests_email_approved      ON public.access_requests (email) WHERE status = 'approved';
CREATE UNIQUE INDEX IF NOT EXISTS idx_access_requests_email_approved_unique ON public.access_requests (email) WHERE status = 'approved';
CREATE UNIQUE INDEX IF NOT EXISTS idx_access_requests_email_pending         ON public.access_requests (email) WHERE status = 'pending';
-- action_pricing_config
CREATE UNIQUE INDEX IF NOT EXISTS action_pricing_config_active_uniq ON public.action_pricing_config (action_key) WHERE is_active = true;
CREATE INDEX        IF NOT EXISTS idx_action_pricing_config_effective ON public.action_pricing_config (action_key, effective_from DESC);
CREATE UNIQUE INDEX IF NOT EXISTS uq_action_pricing_config_active   ON public.action_pricing_config (action_key) WHERE is_active = true;
-- companies
CREATE INDEX IF NOT EXISTS idx_companies_free_credit_granted ON public.companies (free_credit_granted_at) WHERE free_credit_granted_at IS NOT NULL;
-- company_domains
CREATE INDEX IF NOT EXISTS idx_company_domains_company_id          ON public.company_domains (company_id);
CREATE INDEX IF NOT EXISTS idx_company_domains_final_domain        ON public.company_domains (final_domain);
CREATE INDEX IF NOT EXISTS idx_company_domains_input_domain        ON public.company_domains (input_domain);
CREATE INDEX IF NOT EXISTS idx_company_domains_verification_status ON public.company_domains (verification_status);
-- credit_transactions
CREATE UNIQUE INDEX IF NOT EXISTS credit_transactions_idempotency_key_lockdown_unique ON public.credit_transactions (idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX        IF NOT EXISTS idx_credit_tx_org_expiry         ON public.credit_transactions (organization_id, created_at DESC);
-- daily_content_plans (subset; full set re-applied by canonical migrations)
CREATE INDEX IF NOT EXISTS idx_daily_plans_campaign      ON public.daily_content_plans (campaign_id);
CREATE INDEX IF NOT EXISTS idx_daily_plans_campaign_week ON public.daily_content_plans (campaign_id, week_number);
CREATE INDEX IF NOT EXISTS idx_daily_plans_date          ON public.daily_content_plans (date);
CREATE INDEX IF NOT EXISTS idx_daily_plans_status        ON public.daily_content_plans (status);
-- domain_eligibility_cache
CREATE INDEX IF NOT EXISTS domain_eligibility_cache_expires_idx ON public.domain_eligibility_cache (expires_at);
-- email_jobs (idempotency / pending payload re-added by canonical migration)
CREATE INDEX IF NOT EXISTS email_jobs_status_idx ON public.email_jobs (status, created_at);
-- free_credit_claims
CREATE INDEX IF NOT EXISTS idx_fcc_claimed_at  ON public.free_credit_claims (claimed_at DESC);
CREATE INDEX IF NOT EXISTS idx_fcc_user_category ON public.free_credit_claims (user_id, category);
CREATE INDEX IF NOT EXISTS idx_fcc_user_id     ON public.free_credit_claims (user_id);
-- free_credit_profiles
CREATE INDEX IF NOT EXISTS idx_fcp_created  ON public.free_credit_profiles (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_fcp_org_id   ON public.free_credit_profiles (organization_id);
CREATE INDEX IF NOT EXISTS idx_fcp_phone    ON public.free_credit_profiles (phone_number);
CREATE INDEX IF NOT EXISTS idx_fcp_user_id  ON public.free_credit_profiles (user_id);
-- invitations
CREATE UNIQUE INDEX IF NOT EXISTS invitations_active_unique ON public.invitations (lower(email), company_id) WHERE accepted_at IS NULL AND revoked_at IS NULL;
CREATE INDEX        IF NOT EXISTS invitations_company_id_idx ON public.invitations (company_id) WHERE accepted_at IS NULL AND revoked_at IS NULL;
CREATE INDEX        IF NOT EXISTS invitations_token_hash_idx ON public.invitations (token_hash);
-- llm_model_pricing
CREATE INDEX IF NOT EXISTS idx_llm_model_pricing_effective ON public.llm_model_pricing (provider, model_name, kind, effective_from DESC);
CREATE UNIQUE INDEX IF NOT EXISTS uq_llm_model_pricing_active ON public.llm_model_pricing (provider, model_name, kind) WHERE is_active = true;
-- scheduled_posts (subset)
CREATE INDEX IF NOT EXISTS idx_scheduled_posts_campaign      ON public.scheduled_posts (campaign_id);
CREATE INDEX IF NOT EXISTS idx_scheduled_posts_status        ON public.scheduled_posts (status);
CREATE INDEX IF NOT EXISTS idx_scheduled_posts_scheduled_for ON public.scheduled_posts (scheduled_for);
CREATE INDEX IF NOT EXISTS idx_scheduled_posts_user_id       ON public.scheduled_posts (user_id);
-- social_accounts
CREATE INDEX IF NOT EXISTS idx_social_accounts_active     ON public.social_accounts (is_active);
CREATE INDEX IF NOT EXISTS idx_social_accounts_company_id ON public.social_accounts (company_id);
CREATE INDEX IF NOT EXISTS idx_social_accounts_platform   ON public.social_accounts (platform);
CREATE INDEX IF NOT EXISTS idx_social_accounts_user_id    ON public.social_accounts (user_id);
-- super_admin_audit_logs
CREATE INDEX IF NOT EXISTS super_admin_audit_logs_actor_idx ON public.super_admin_audit_logs (actor_user_id, created_at DESC);
-- unified_transactions
CREATE INDEX IF NOT EXISTS idx_unified_txn_org_created ON public.unified_transactions (organization_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_unified_txn_source      ON public.unified_transactions (source_type, created_at DESC);
-- usage_events
CREATE INDEX IF NOT EXISTS idx_usage_events_org      ON public.usage_events (organization_id, created_at);
CREATE INDEX IF NOT EXISTS idx_usage_events_campaign ON public.usage_events (campaign_id, created_at);
-- user_company_roles
CREATE INDEX IF NOT EXISTS idx_user_company_roles_user_company ON public.user_company_roles (user_id, company_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_user_company_roles_user_company_active ON public.user_company_roles (user_id, company_id) WHERE status = 'active';
-- user_preferences
CREATE INDEX IF NOT EXISTS idx_user_preferences_user_id ON public.user_preferences (user_id);
-- users
CREATE INDEX IF NOT EXISTS idx_users_active_company_id ON public.users (active_company_id) WHERE active_company_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_users_onboarding_state  ON public.users (onboarding_state) WHERE onboarding_state <> 'active';
CREATE UNIQUE INDEX IF NOT EXISTS users_supabase_uid_key ON public.users (supabase_uid) WHERE supabase_uid IS NOT NULL;

-- End of baseline.
